`timescale 1ns/1ps

// File-driven test for emg_feature_bank. Reads bank_stim.txt (one frame
// per line, eight space-separated signed decimals, generated by
// tools/emg_reference.py), feeds the samples channel-serialized like the
// ADS1299 controller does, and writes bank_out.csv
// (type,channel,id,sequence,payload). The Python model compares payloads.
module emg_feature_bank_tb;
    reg clk = 1'b0;
    reg rst_n = 1'b0;
    reg sample_valid = 1'b0;
    reg [2:0] sample_channel = 3'd0;
    reg signed [23:0] sample_data = 24'sd0;
    wire feature_valid;
    wire [3:0] feature_id;
    wire [2:0] feature_channel;
    wire [31:0] feature_data;
    wire [15:0] feature_sequence;
    integer stim_fd, out_fd, code;
    integer v0, v1, v2, v3, v4, v5, v6, v7;
    integer frames, words, errors;
    integer last_seq, have_last;

    always #5 clk = ~clk;

    emg_feature_bank dut (
        .clk(clk), .rst_n(rst_n),
        .sample_valid(sample_valid), .sample_channel(sample_channel),
        .sample_data(sample_data),
        .feature_ready(1'b1), .feature_valid(feature_valid),
        .feature_id(feature_id), .feature_channel(feature_channel),
        .feature_data(feature_data), .feature_sequence(feature_sequence)
    );

    // feature_ready is tied high, so every cycle with feature_valid
    // accepts exactly one word.
    always @(posedge clk) begin
        if (feature_valid) begin
            words = words + 1;
            if (feature_id > 4) begin
                errors = errors + 1;
                $display("bad feature id %0d", feature_id);
            end
            if (have_last && feature_sequence !== (last_seq + 1)) begin
                errors = errors + 1;
                $display("sequence gap: %0d after %0d", feature_sequence, last_seq);
            end
            last_seq = feature_sequence;
            have_last = 1;
            $fdisplay(out_fd, "2,%0d,%0d,%0d,%0d",
                      feature_channel, feature_id, feature_sequence, feature_data);
        end
    end

    task send_beat;
        input [2:0] ch;
        input signed [23:0] val;
        begin
            @(negedge clk);
            sample_channel = ch;
            sample_data = val;
            sample_valid = 1'b1;
            @(negedge clk);
            sample_valid = 1'b0;
        end
    endtask

    initial begin
        stim_fd = $fopen("bank_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("EMG feature bank TB FAILED: cannot open bank_stim.txt");
            $finish;
        end
        out_fd = $fopen("bank_out.csv", "w");
        $fdisplay(out_fd, "type,channel,id,sequence,payload");
        frames = 0;
        words = 0;
        errors = 0;
        have_last = 0;
        repeat (4) @(posedge clk);
        rst_n = 1'b1;
        repeat (4) @(posedge clk);
        forever begin
            code = $fscanf(stim_fd, "%d %d %d %d %d %d %d %d",
                           v0, v1, v2, v3, v4, v5, v6, v7);
            if (code != 8) begin
                repeat (200) @(posedge clk);
                $fclose(stim_fd);
                $fclose(out_fd);
                if (errors == 0)
                    $display("EMG feature bank TB PASSED: frames=%0d words=%0d",
                             frames, words);
                else
                    $display("EMG feature bank TB FAILED: frames=%0d words=%0d errors=%0d",
                             frames, words, errors);
                $finish;
            end
            send_beat(3'd0, v0[23:0]);
            send_beat(3'd1, v1[23:0]);
            send_beat(3'd2, v2[23:0]);
            send_beat(3'd3, v3[23:0]);
            send_beat(3'd4, v4[23:0]);
            send_beat(3'd5, v5[23:0]);
            send_beat(3'd6, v6[23:0]);
            send_beat(3'd7, v7[23:0]);
            repeat (2) @(posedge clk);
            frames = frames + 1;
        end
    end
endmodule

